type Task = { name: string; onProgress?: (percent: number) => void }

async function runTask(task: Task): Promise<string> {
    for (const p of [50, 100]) {
        await Promise.resolve()          // haqiqiy ishni taqlid qilamiz
        task.onProgress?.(p)             // callback bo'lsa — xabar beramiz
    }
    return `${task.name} tugadi`
}

