const Permission = {
    None: 0,
    Read: 1,      // 0001
    Write: 2,     // 0010
    Delete: 4,    // 0100
    Admin: 8,     // 1000
} as const

function describe(flags: number): string {
    const names: string[] = []
    if (flags & Permission.Read) names.push("o'qish")
    if (flags & Permission.Write) names.push("yozish")
    if (flags & Permission.Delete) names.push("o'chirish")
    if (flags & Permission.Admin) names.push("admin")
    return names.length ? names.join(", ") : "ruxsat yo'q"
}

const viewer = Permission.Read
const editor = Permission.Read | Permission.Write
const admin = Permission.Read | Permission.Write | Permission.Delete | Permission.Admin

console.log("Viewer:", describe(viewer))
console.log("Editor:", describe(editor))
console.log("Admin:", describe(admin))

function hexToRgb(hex: string): { r: number; g: number; b: number } {
    const value = parseInt(hex.replace("#", ""), 16)
    return {
        r: (value >> 16) & 0xff,
        g: (value >> 8) & 0xff,
        b: value & 0xff,
    }
}

function rgbToHex(r: number, g: number, b: number): string {
    return "#" + ((r << 16) | (g << 8) | b).toString(16).padStart(6, "0")
}

