const toInt = (s: string) => s.split(".").reduce((a, o) => ((a << 8) | Number(o)) >>> 0, 0)
const inSubnet = (addr: string, net: string, cidr: number) => {
    const m = (0xffffffff << (32 - cidr)) >>> 0
    return ((toInt(addr) & m) >>> 0) === ((toInt(net) & m) >>> 0)
}
