function hash(text: string): number {
    let h = 5381
    for (const ch of text) {
        h = ((h << 5) + h + ch.codePointAt(0)!) | 0     // h * 33 + kod, 32 bitda qoladi
    }
    return h >>> 0                                      // ishorasiz 0..2^32-1
}

