class BitSet {
    private words: Uint32Array
    constructor(size: number) {
        this.words = new Uint32Array(Math.ceil(size / 32))
    }
    add(i: number) { this.words[i >>> 5] |= 1 << (i & 31) }
    has(i: number) { return (this.words[i >>> 5] & (1 << (i & 31))) !== 0 }
    count() {
        let c = 0
        for (const w of this.words) { let x = w; while (x) { x &= x - 1; c++ } }
        return c
    }
}

const seen = new BitSet(1000)
for (const id of [3, 64, 999, 64]) seen.add(id)
console.log(seen.has(64), seen.has(65), seen.has(999), "jami:", seen.count())

